\label{cor:generator_encoding}
    Let $N_1$ and $N_2$ be two simple, $k$-crucial, semi-directed networks on~$\mathcal{X}$.                                                                                        
    If $\mathcal{S}_k (N_1 ) \simeq\mathcal{S}_k (N_2)$, then $\mathrm{gen} (N_1) \cong \mathrm{gen} (N_2)$.

\label{lem:equivalence_class_encoding}
    Let $N_1$ and $N_2$ be two simple, $k$-crucial, semi-directed networks on~$\mathcal{X}$.                                                                                                                                                   
    If $\mathcal{S}_{k+1} (N_1 ) \simeq \mathcal{S}_{k+1} (N_2)$, then $N_1$ and $N_2$ are leaf-side consistent.

\label{lem:generator14}
    Let $N_1$ and $N_2$ be two simple, strictly level-3, semi-directed networks on $\mathcal{X}$ having the same generator~$G$ of type~14. 
    \begin{enumerate}[label=(\alph*)]
        \item If $\mathcal{S}_{4} (N_1 ) \simeq \mathcal{S}_{4} (N_2)$, then $N_1$ and $N_2$ are isomorphic modulo reversing the top side.
        \item If $\mathcal{S}_{5} (N_1 ) \simeq \mathcal{S}_{5} (N_2)$, then $N_1$ and $N_2$ are isomorphic.
    \end{enumerate}

\label{thm:main-encoding}
Let $\mathcal{L}_3$ be the class of binary, level-3, semi-directed networks. Then,
\begin{enumerate}[label=(\alph*)]
    \item $\mathcal{L}_3$ is encoded by quarnets, modulo reversing the top side of the type~14 blobs; and
    \item $\mathcal{L}_3$ is encoded by quinnets.
\end{enumerate}
